    if not re.fullmatch(r'[A-Za-z0-9](?:[A-Za-z0-9.-]{0,251}[A-Za-z0-9])?', str(endpoint)):
        raise ValueError('invalid endpoint')
    args = ['openssl', 's_client', '-connect', endpoint]
    return runner.run(args, timeout=30)

