def tar_extract_safe(archive):
    from pathlib import Path
    import re
    safe_archive = Path(str(archive)).name
    if not re.fullmatch(r'(?!-)[A-Za-z0-9._-]{1,128}', safe_archive):
        raise ValueError('invalid archive')
    if not safe_archive.endswith(('.tar', '.tar.gz', '.tgz')):
        raise ValueError('invalid archive extension')
    result = subprocess.run(['tar', '-xf', safe_archive], capture_output=True, text=True, check=True)
    return result.stdout

